update_rule.pseudocode:
if day < campaign_start_day:
  I = campaign_base_intensity
elif campaign_start_day <= day < campaign_start_day + campaign_ramp_days:
  r = (day - campaign_start_day) / max(1, campaign_ramp_days)
  I = campaign_base_intensity + r * (campaign_max_intensity - campaign_base_intensity)
else:
  t_since_peak = day - (campaign_start_day + campaign_ramp_days)
  I = campaign_max_intensity * exp(- t_since_peak / max(1, campaign_decay_days))
if campaign_pulse_interval > 0 and day % campaign_pulse_interval == 0:
  I = min(1.0, I + campaign_pulse_magnitude)
emit signal.campaign_intensity = clamp(I, 0, 1)
